(()=>{'use strict';const body=document.body,nav=document.querySelector('.site-nav'),toggle=document.querySelector('.nav-toggle');if(nav&&toggle){toggle.addEventListener('click',()=>{const open=!nav.classList.contains('is-open');nav.classList.toggle('is-open',open);toggle.setAttribute('aria-expanded',String(open));body.classList.toggle('nav-open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('is-open');toggle.setAttribute('aria-expanded','false');body.classList.remove('nav-open')}))}document.querySelectorAll('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());const reveals=[...document.querySelectorAll('.reveal:not(.is-visible)')];if('IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -25px'});reveals.forEach(el=>io.observe(el))}else reveals.forEach(el=>el.classList.add('is-visible'));const modal=document.querySelector('[data-lightbox-modal]');if(modal){const img=modal.querySelector('img'),cap=modal.querySelector('figcaption'),close=()=>{modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');body.classList.remove('lightbox-open')};document.querySelectorAll('[data-lightbox]').forEach(btn=>btn.addEventListener('click',()=>{img.src=btn.dataset.lightbox||'';img.alt=btn.dataset.caption||'Project image';cap.textContent=btn.dataset.caption||'';modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');body.classList.add('lightbox-open')}));modal.querySelector('[data-lightbox-close]')?.addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()})}const filters=[...document.querySelectorAll('[data-gallery-filter]')],items=[...document.querySelectorAll('[data-category]')];filters.forEach(btn=>btn.addEventListener('click',()=>{const f=btn.dataset.galleryFilter||'all';filters.forEach(b=>b.classList.toggle('is-active',b===btn));items.forEach(item=>item.classList.toggle('is-hidden',f!=='all'&&!(item.dataset.category||'').split(' ').includes(f)))}));const form=document.querySelector('[data-preview-form]');if(form){form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;form.querySelector('.form-status')?.classList.add('is-visible')})}})();